 for(const [side,i]of[['home',0],['away',1]]){const goal=analysis?.teams?.[side]?.goalForm;if(goal?.matches&&Number.isFinite(goal.weightedGoalsFor)&&Number.isFinite(goal.weightedGoalsAgainst))add(match.teams[i].name+tr(' · Son ',' · Last ')+goal.matches+tr(' maç, ağırlıklı gol ortalaması: ',' matches, weighted goals: ')+goal.weightedGoalsFor.toFixed(2)+' / '+goal.weightedGoalsAgainst.toFixed(2)+tr(' (atılan / yenen)',' (scored / conceded)'));}
 const outlook=chosenPayload?.outlook,interval=outlook?.totalGoalsInterval;if(interval)add(tr('Modelin toplam gol aralığı (%','Model total-goals interval (')+Math.round(interval.mass*100)+tr(' olasılık): ','% probability): ')+interval.low+'–'+interval.high+tr(' gol.',' total goals.'));if(Number.isFinite(outlook?.underdogWinProbability))add(tr('Daha düşük kazanma olasılığı verilen takımın galibiyet ihtimali: ','Win probability for the model underdog: ')+Math.round(outlook.underdogWinProbability*100)+'%');if(chosenPayload?.publishedAt)add(tr('Tahminin sabitlendiği zaman: ','Forecast fixed at: ')+new Intl.DateTimeFormat(lang==='tr'?'tr-TR':'en-GB',{dateStyle:'short',timeStyle:'short',timeZone:lang==='en'?'UTC':'Europe/Istanbul'}).format(new Date(chosenPayload.publishedAt))+tr(' TSİ. Maça beş gün kala kadrolar henüz kesinleşmemiş olabilir.',' UTC. Lineups may remain unconfirmed five days before kick-off.'));
