async function refreshWaitingLineups(){
 if(refreshingLineups||!matchSelected||exporting||document.hidden||$('studio').hidden||location.protocol==='file:'||!chosenPayload?.fixture?.id||chosenPayload?.fixture?.concept)return;
 const selected=chosenPayload,id=selected.fixture.id;if(Date.now()-(selected.lineupsCheckedAt||0)<90000)return;refreshingLineups=true;
 try{const r=await fetch('api.php?action=lineups&id='+encodeURIComponent(id),{cache:'no-store',signal:AbortSignal.timeout(25000)});if(!r.ok)return;const snapshot=await window.SekmeClubRosters.complete(await r.json(),selected.fixture);if(selected!==chosenPayload||exporting)return;selected.lineupsCheckedAt=Date.now();if(started||running){for(let i=0;i<2;i++){const current=match.lineups?.[i],fresh=snapshot.teams?.[i];if(!current||!fresh)continue;if(fresh.coach)current.coach={...fresh.coach};if(!current.bench?.length&&fresh.bench?.length)current.bench=fresh.bench;}dirty=true;return;}if(lineupIdentity(snapshot)!==lineupIdentity(selected.lineups)){selected.lineups=snapshot;await loadFixture(selected,chosenMode,chosenTarget);}}catch{}finally{refreshingLineups=false;}
}
